INSERT INTO `cms_pages` VALUES (1,'Why choose Sports Junction','why-choose-sports-junction',NULL,NULL,'ABOUT','<h2>Why Choose Sports Junction</h2><p>Sports Junction is India’s dedicated B2B manufacturing and wholesale sports goods marketplace. We bridge international and domestic sports brands, academies, clubs, and retailers directly with certified Indian manufacturers in Jalandhar, Meerut, Gurgaon, and beyond.</p><h3>Direct Factory Access</h3><p>Eliminate unnecessary broker markups and negotiate directly with verified factories producing international-standard sports equipment.</p>',NULL,1,1,'2026-10-15 11:56:28','2026-10-16 16:16:40'),(2,'Corporate responsibility','corporate-responsibility',NULL,NULL,'ABOUT','<h2>Corporate & Social Responsibility</h2><p>Sports Junction is committed to sustainable sports equipment manufacturing, fair factory labor standards, child-labor-free sporting goods production, and eco-friendly packaging across our certified vendor network.</p>',NULL,2,1,'2026-10-15 11:56:28','2026-10-16 16:16:40'),(3,'Careers','careers',NULL,NULL,'ABOUT','<h2>Careers at Sports Junction</h2><p>Join the team modernizing India’s \\$1.5B+ sports export manufacturing sector. We are always seeking passionate individuals across engineering, supply chain logistics, B2B business development, and quality audit management.</p>',NULL,3,1,'2026-10-15 11:56:28','2026-10-16 16:16:40'),(4,'Secure Payments','secure-payments',NULL,NULL,'ORDER_PROTECTION','<h2>Secure B2B Payment Processing</h2><p>All transactions, escrow safeguards, and commercial invoices comply with standard commercial banking safeguards and PCI DSS compliance protocols.</p>',NULL,1,1,'2026-10-15 11:56:28','2026-10-16 16:16:40'),(5,'Guaranteed Delivery','guaranteed-delivery',NULL,NULL,'ORDER_PROTECTION','<h2>Guaranteed Delivery & Shipping SLA</h2><p>We ensure verified factory dispatch dates and real-time container tracking with compensation terms for unexcused manufacturing delays.</p>',NULL,2,1,'2026-10-15 11:56:28','2026-10-16 16:16:40'),(6,'Inspection Services','inspection-services',NULL,NULL,'ORDER_PROTECTION','<h2>Production Monitoring & Third-Party Inspection</h2><p>Buyers can request pre-shipment quality inspection, material tensile testing, and factory compliance audits before container loading.</p>',NULL,3,1,'2026-10-15 11:56:28','2026-10-16 16:16:40'),(7,'Policies and rules','policies-and-rules',NULL,NULL,'ORDER_PROTECTION','<h2>Platform Policies & Marketplace Guidelines</h2><p>Sports Junction maintains strict trading conduct. Direct off-platform payment diversion, counterfeit manufacturing, and deceptive specifications result in immediate vendor suspension and forfeiture of platform verification badges.</p>',NULL,4,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(8,'Verified manufacturers','verified-manufacturers',NULL,NULL,'SOURCE','<h2>Verified Indian Manufacturers</h2><p>Explore audited manufacturing facilities with verified GST, IEC export licenses, and verified plant machinery in Meerut, Jalandhar, and Ahmedabad.</p>','/products?verified=1',1,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(9,'Request for Quotation (RFQ)','request-for-quotation',NULL,NULL,'SOURCING','<h2>Request for Quotation (RFQ)</h2><p>Submit customized bulk requirements, OEM specifications, tech packs, or sample evaluation requests directly to verified suppliers.</p>','/page/request-for-quotation',2,1,'2026-10-15 11:56:28','2026-10-16 16:16:40'),(10,'Buyer Help Center','buyer-help-center',NULL,NULL,'ORDER_PROTECTION','<h2>Buyer Help Center</h2><p>Comprehensive guides on creating requests for quotation, evaluating vendor audit tags, arranging sample orders, and managing multi-supplier procurement.</p>',NULL,4,1,'2026-10-15 11:56:28','2026-10-16 16:16:40'),(11,'Live chat','live-chat',NULL,NULL,'HELP_CENTER','<h2>Real-Time Live Chat & Direct Negotiation</h2><p>Sports Junction features built-in real-time chat with instant document exchange and binding counter-offers. Open the chat widget at the bottom right of any product page to chat directly with verified factory representatives.</p>','/buyer/messages',2,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(12,'Sell on Sports Junction','sell-on-sports-junction',NULL,NULL,'SELL','<h2>Sell on Sports Junction — Supplier Onboarding</h2><p>Expand your sports manufacturing factory to international importers in the USA, UK, Europe, Australia, and GCC. Register your factory and start receiving direct bulk purchase orders.</p>','/seller/login',1,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(13,'Become a Verified Supplier','become-verified-supplier',NULL,NULL,'SELL','<h2>Become a Verified Sports Junction Manufacturer</h2><p>Undergo our comprehensive background verification and facility audit to earn the coveted Verified Supplier Badge, boosting your catalog visibility by over 300%.</p>','/seller/login',2,1,'2026-10-15 11:56:28','2026-10-15 11:56:28'),(14,'Cricket Bats & Pads','cricket-bats-pads',NULL,NULL,'TOP_SECTORS','<h2>Cricket Bats, Pads & Protective Equipment</h2><p>Source English Willow and Kashmir Willow cricket bats, batting pads, wicket keeping gloves, and helmets directly from premier manufacturers in Meerut and Jalandhar.</p>','/category/cricket-and-field-sports',1,1,'2026-10-16 16:16:40','2026-10-16 16:16:40'),(15,'Match Footballs','match-footballs',NULL,NULL,'TOP_SECTORS','<h2>Match & Training Footballs</h2><p>Hand-stitched, hybrid, and thermally bonded FIFA-standard footballs manufactured with certified polyurethane and bladder retention technologies.</p>','/category/football-and-inflatables',2,1,'2026-10-16 16:16:40','2026-10-16 16:16:40'),(16,'Agility Hurdles & Ladders','agility-hurdles-ladders',NULL,NULL,'TOP_SECTORS','<h2>Speed, Agility & Fitness Training Equipment</h2><p>High-durability speed hurdles, agility ladders, marker cones, and slalom poles for professional sports academies and conditioning centers.</p>','/category/agility-and-speed-training',3,1,'2026-10-16 16:16:40','2026-10-16 16:16:40'),(17,'Commercial Gym Equipment','commercial-gym-equipment',NULL,NULL,'TOP_SECTORS','<h2>Commercial & Functional Gym Equipment</h2><p>Olympic barbells, rubber bumper plates, cast iron kettlebells, and heavy-duty strength power cages crafted for commercial gym facilities.</p>','/category/sports-and-fitness',4,1,'2026-10-16 16:16:40','2026-10-16 16:16:40'),(18,'Sportswear & Uniforms','sportswear-uniforms',NULL,NULL,'TOP_SECTORS','<h2>Custom Sportswear & Team Uniforms</h2><p>Breathable, moisture-wicking sublimation printed team jerseys, training tracksuits, and athletic performance wear tailored to OEM/ODM specifications.</p>','/category/apparel-and-accessories',5,1,'2026-10-16 16:16:40','2026-10-16 16:16:40'),(19,'Direct Factory Catalog','direct-factory-catalog',NULL,NULL,'SOURCING','<h2>Direct Factory Catalog</h2><p>Browse thousands of factory-direct sporting equipment listings verified for manufacturing authenticity, tier pricing, and export readiness.</p>','/products',1,1,'2026-10-16 16:16:40','2026-10-16 16:16:40'),(20,'Contact Us & Support','contact-us-support',NULL,NULL,'SOURCING','<h2>Contact & B2B Trade Desk</h2><p>Get in touch with our centralized B2B trade desk for bulk orders, vendor verification, or technical platform assistance.</p>','/contact',3,1,'2026-10-16 16:16:40','2026-10-16 16:16:40'),(21,'Container Freight Logistics','container-freight-logistics',NULL,NULL,'SOURCING','<h2>Container Freight & Export Logistics</h2><p>Sports Junction coordinates with leading freight forwarding partners to provide FOB, CIF, and DDP sea and air shipping logistics from Indian dry ports and seaports worldwide.</p>',NULL,4,1,'2026-10-16 16:16:40','2026-10-16 16:16:40'),(22,'XML Sitemap','xml-sitemap',NULL,NULL,'SOURCING','<h2>XML Sitemap</h2><p>Search engine index file for all products, categories, and marketplace pages.</p>','/sitemap.xml',5,1,'2026-10-16 16:16:40','2026-10-16 16:16:40'),(23,'Super Admin Portal →','super-admin-portal',NULL,NULL,'PLATFORM_ADMIN','<h2>Super Admin Portal</h2><p>Dedicated gateway for sports junction administrative management and marketplace operations.</p>','/admin/login',1,1,'2026-10-16 16:16:40','2026-10-16 16:16:40'),(24,'Master CRUD Management','master-crud-management',NULL,NULL,'PLATFORM_ADMIN','<h2>Master CRUD Management</h2><p>Management portal for product certificates, certification tags, categories, subcategories, units, and site branding.</p>','/admin/dashboard',2,1,'2026-10-16 16:16:40','2026-10-16 16:16:40'),(25,'Product Publishing Hub','product-publishing-hub',NULL,NULL,'PLATFORM_ADMIN','<h2>Product Publishing Hub</h2><p>Review submitted supplier goods, audit OEM specifications, approve catalog listings, and highlight featured merchandise.</p>','/admin/products',3,1,'2026-10-16 16:16:40','2026-10-16 16:16:40'),(26,'Terms & Manufacturing SLA','terms-manufacturing-sla',NULL,NULL,'PLATFORM_ADMIN','<h2>Terms of Service & Manufacturing SLA</h2><p>Review our standard service level agreements governing sample delivery timelines, manufacturing tolerance standards, and dispute resolution guidelines.</p>','/page/policies-and-rules',4,1,'2026-10-16 16:16:40','2026-10-16 16:16:40'),(27,'Test Audit Compliance Guide','test-audit-compliance-1792148044',NULL,NULL,'SOURCING','<p>Detailed testing content for B2B sports factory audit.</p>',NULL,99,1,'2026-10-16 16:24:04','2026-10-16 16:24:04');
/*!40000 ALTER TABLE `cms_pages` ENABLE KEYS */;
UNLOCK TABLES;

